Mã nguồn mẫu cho cli_interactive_and_error_handling:
# Kịch bản CLI tương tác mua vé phim kèm kiểm thử lỗi logic nhập liệu
print("=== HỆ THỐNG XÁC THỰC TUỔI VÀO PHÒNG CHIẾU ===")
tuoi_nhap = input("Vui lòng nhập tuổi của bạn (chỉ nhập số): ")

# Sử dụng phương thức .isdigit() để kiểm tra chuỗi có hợp lệ là số nguyên không
if tuoi_nhap.isdigit():
    tuoi = int(tuoi_nhap)
    if tuoi >= 18:
        print("Kết quả: Bạn đủ điều kiện vào phòng chiếu phim dành cho người lớn.")
    else:
        print("Kết quả: Bạn chỉ được phép vào phòng chiếu phim dành cho trẻ em.")
else:
    print("Lỗi logic: Yêu cầu nhập đúng chữ số nguyên dương đại diện cho số tuổi!")

Mã nguồn mẫu cho ung_dung_cli_hoan_chinh:
print("--- ỨNG DỤNG TÍNH ĐIỂM TRUNG BÌNH ---")
try:
    diem_toan = float(input("Nhập điểm Toán: "))
    diem_van = float(input("Nhập điểm Văn: "))
    if 0 <= diem_toan <= 10 and 0 <= diem_van <= 10:
        dtb = (diem_toan + diem_van) / 2
        print(f"Điểm trung bình của học sinh là: {dtb:.2f}")
    else:
        print("Lỗi: Điểm số phải nằm trong khoảng từ 0 đến 10.")
except ValueError:
    print("Lỗi: Vui lòng chỉ nhập số thực cho điểm!")

