Mã nguồn mẫu cho nested_if_else_sample:
age = 20
is_student = True

# Kịch bản kiểm tra độ tuổi và trạng thái thẻ học sinh để áp dụng giá vé
if age < 18:
    ticket_price = 50000
else:
    if is_student:
        ticket_price = 70000
    else:
        ticket_price = 100000

print('Gia ve: ' + str(ticket_price) + ' VND')

