income = 15000000
credit_score = 650

# He thong phan loai duyet han muc tin dung dua tren thu nhap va diem tin dung
if income >= 20000000:
    loan_status = 'Phe duyet cao' if credit_score >= 700 else 'Phe duyet trung binh'
elif income >= 10000000:
    if credit_score >= 600:
        loan_status = 'Phe duyet tieu chuan'
    else:
        loan_status = 'Yeu cau tai san bao dam'
else:
